-- 10 template dashboard gratis baru (multi-halaman). Gratis = hanya foto, tanpa demo live.
-- Jalankan di Supabase Dashboard → SQL Editor. Aman dijalankan ulang (upsert berdasarkan slug).
-- Gambar ada di repo shop: public/templates/<folder>/ (card.webp, desktop-1..4.webp, mobile-1.webp).

insert into public.shop_templates
  (slug, title, summary, description, category, tech_stack, price, demo_url, thumbnail_url, screenshots, mobile_screenshots, features, version, file_size, storage_file_path, status)
values
('ledgerly-accounting-dashboard', 'Ledgerly Accounting Dashboard', 'Dashboard keuangan usaha kecil: arus kas, invoice, pengeluaran, dan saldo klien dalam 4 halaman.', 'Dashboard akuntansi untuk usaha kecil atau freelancer. Halaman Overview berisi kartu kas, pemasukan, pengeluaran, dan invoice belum dibayar, grafik pemasukan vs pengeluaran, serta pengeluaran per kategori. Halaman Invoices dengan filter status dan pencarian, halaman Expenses dengan filter bulan dan kategori, serta direktori klien beserta sisa tagihannya.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-accounting-dashboard/card.webp', array['/templates/free-accounting-dashboard/desktop-1.webp', '/templates/free-accounting-dashboard/desktop-2.webp', '/templates/free-accounting-dashboard/desktop-3.webp', '/templates/free-accounting-dashboard/desktop-4.webp'], array['/templates/free-accounting-dashboard/mobile-1.webp'], array['4 halaman: Overview, Invoices, Expenses, Clients', 'Grafik batang, donut, dan sparkline SVG tanpa library', 'Filter status, pencarian, dan urutan kolom', 'Sidebar bisa diciutkan, menu geser di HP'], 'v1.0.0', null, 'free-accounting-dashboard/free-accounting-dashboard-v1.0.0.zip', 'Terbit'),
('medika-clinic-dashboard', 'Medika Clinic Dashboard', 'Dashboard klinik umum: antrean pasien, jadwal janji temu mingguan, data pasien, dan dokter jaga.', 'Dashboard untuk resepsionis dan admin klinik. Overview menampilkan antrean pasien yang sedang berjalan dan dokter jaga, halaman Appointments berisi kalender mingguan per jam, halaman Patients berisi data pasien (BPJS dan Umum) dengan pencarian dan paginasi, serta direktori dokter dengan filter spesialis dan status jaga.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-clinic-dashboard/card.webp', array['/templates/free-clinic-dashboard/desktop-1.webp', '/templates/free-clinic-dashboard/desktop-2.webp', '/templates/free-clinic-dashboard/desktop-3.webp', '/templates/free-clinic-dashboard/desktop-4.webp'], array['/templates/free-clinic-dashboard/mobile-1.webp'], array['4 halaman: Overview, Appointments, Patients, Doctors', 'Antrean pasien dan kalender janji temu mingguan', 'Data pasien dengan pencarian, urutan, dan paginasi', 'Grafik SVG tanpa library, menu geser di HP'], 'v1.0.0', null, 'free-clinic-dashboard/free-clinic-dashboard-v1.0.0.zip', 'Terbit'),
('orbit-store-admin-dashboard', 'Orbit Store Admin Dashboard', 'Dashboard admin toko online: pendapatan, pesanan per status, katalog produk, dan data pelanggan.', 'Dashboard untuk mengelola toko online kecil. Overview berisi kartu KPI dan grafik pendapatan, halaman Orders dengan kartu status pesanan dan pencarian, halaman Products dengan filter kategori, tampilan grid atau daftar, dan tombol aktif/nonaktif produk, serta direktori pelanggan dengan segmen VIP, Loyal, dan New.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-ecommerce-dashboard/card.webp', array['/templates/free-ecommerce-dashboard/desktop-1.webp', '/templates/free-ecommerce-dashboard/desktop-2.webp', '/templates/free-ecommerce-dashboard/desktop-3.webp', '/templates/free-ecommerce-dashboard/desktop-4.webp'], array['/templates/free-ecommerce-dashboard/mobile-1.webp'], array['4 halaman: Overview, Orders, Products, Customers', 'Status pesanan dan tombol aktif/nonaktif produk', 'Tampilan produk grid atau daftar', 'Grafik SVG tanpa library, menu geser di HP'], 'v1.0.0', null, 'free-ecommerce-dashboard/free-ecommerce-dashboard-v1.0.0.zip', 'Terbit'),
('pulse-gym-membership-dashboard', 'Pulse Gym Membership Dashboard', 'Dashboard gym dan fitness: member aktif, jadwal kelas mingguan, dan check-in di meja depan.', 'Dashboard admin gym dengan sidebar gelap dan aksen hijau lime. Overview berisi KPI member, grafik check-in per jam, dan komposisi paket membership. Halaman Members dengan status aktif, hampir habis, habis, dan dibekukan, jadwal kelas mingguan per jenis kelas, serta halaman check-in yang langsung menampilkan status member dari ID-nya.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-gym-dashboard/card.webp', array['/templates/free-gym-dashboard/desktop-1.webp', '/templates/free-gym-dashboard/desktop-2.webp', '/templates/free-gym-dashboard/desktop-3.webp', '/templates/free-gym-dashboard/desktop-4.webp'], array['/templates/free-gym-dashboard/mobile-1.webp'], array['4 halaman: Overview, Members, Classes, Check-ins', 'Cek status member dari ID di meja depan', 'Jadwal kelas mingguan berwarna per jenis kelas', 'Sidebar gelap bisa diciutkan, menu geser di HP'], 'v1.0.0', null, 'free-gym-dashboard/free-gym-dashboard-v1.0.0.zip', 'Terbit'),
('haven-hotel-booking-dashboard', 'Haven Hotel Booking Dashboard', 'Dashboard hotel butik: tingkat hunian, reservasi, denah kamar per lantai, dan data tamu.', 'Dashboard front desk untuk hotel atau penginapan kecil. Overview berisi tingkat hunian, kedatangan hari ini, dan grafik okupansi. Halaman Reservations dengan status booking dan pencarian, denah 40 kamar di 4 lantai yang diberi warna sesuai status, serta direktori tamu dengan jumlah menginap dan total belanja.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-hotel-dashboard/card.webp', array['/templates/free-hotel-dashboard/desktop-1.webp', '/templates/free-hotel-dashboard/desktop-2.webp', '/templates/free-hotel-dashboard/desktop-3.webp', '/templates/free-hotel-dashboard/desktop-4.webp'], array['/templates/free-hotel-dashboard/mobile-1.webp'], array['4 halaman: Overview, Reservations, Rooms, Guests', 'Denah kamar per lantai dengan status berwarna', 'Reservasi dengan filter status dan pencarian', 'Grafik SVG tanpa library, menu geser di HP'], 'v1.0.0', null, 'free-hotel-dashboard/free-hotel-dashboard-v1.0.0.zip', 'Terbit'),
('pustaka-library-dashboard', 'Pustaka Library Dashboard', 'Dashboard perpustakaan sekolah atau kampus: peminjaman, katalog buku, sirkulasi, dan anggota.', 'Dashboard perpustakaan bernuansa kertas yang hangat. Overview berisi buku dipinjam, jatuh tempo, dan denda, katalog buku dengan sampul berwarna dan ketersediaan eksemplar, meja sirkulasi untuk pinjam dan kembali buku dengan hitungan tanggal otomatis, serta direktori anggota dengan export CSV.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-library-dashboard/card.webp', array['/templates/free-library-dashboard/desktop-1.webp', '/templates/free-library-dashboard/desktop-2.webp', '/templates/free-library-dashboard/desktop-3.webp', '/templates/free-library-dashboard/desktop-4.webp'], array['/templates/free-library-dashboard/mobile-1.webp'], array['4 halaman: Overview, Catalog, Circulation, Members', 'Pinjam dan kembali buku dengan tanggal otomatis', 'Katalog buku dengan filter genre', 'Export CSV, menu geser di HP'], 'v1.0.0', null, 'free-library-dashboard/free-library-dashboard-v1.0.0.zip', 'Terbit'),
('lumbung-loan-management-dashboard', 'Lumbung Loan Management Dashboard', 'Dashboard koperasi simpan pinjam: portofolio pinjaman, pengajuan, jadwal angsuran, dan anggota.', 'Dashboard untuk koperasi atau lembaga simpan pinjam. Overview berisi total pinjaman berjalan dan kesehatan pembayaran, halaman pengajuan pinjaman dengan status dan kalkulator angsuran, jadwal angsuran dengan filter lunas, jatuh tempo, dan terlambat, serta direktori anggota dengan simpanan dan skor kredit.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-loan-dashboard/card.webp', array['/templates/free-loan-dashboard/desktop-1.webp', '/templates/free-loan-dashboard/desktop-2.webp', '/templates/free-loan-dashboard/desktop-3.webp', '/templates/free-loan-dashboard/desktop-4.webp'], array['/templates/free-loan-dashboard/mobile-1.webp'], array['4 halaman: Overview, Loans, Installments, Members', 'Kalkulator angsuran langsung', 'Jadwal angsuran dengan filter status', 'Grafik area dan donut SVG, menu geser di HP'], 'v1.0.0', null, 'free-loan-dashboard/free-loan-dashboard-v1.0.0.zip', 'Terbit'),
('kirim-logistics-dashboard', 'Kirim Logistics Dashboard', 'Dashboard ekspedisi dan kurir: pengiriman per status, lacak resi, rute, dan armada kendaraan.', 'Dashboard operasional untuk jasa pengiriman paket. Overview berisi KPI pengiriman, grafik status per hari, dan peta rute, halaman Shipments dengan lima status pengiriman, halaman pelacakan resi dengan riwayat perjalanan paket, serta daftar armada beserta kurir dan kapasitas muatnya.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-logistics-dashboard/card.webp', array['/templates/free-logistics-dashboard/desktop-1.webp', '/templates/free-logistics-dashboard/desktop-2.webp', '/templates/free-logistics-dashboard/desktop-3.webp', '/templates/free-logistics-dashboard/desktop-4.webp'], array['/templates/free-logistics-dashboard/mobile-1.webp'], array['4 halaman: Overview, Shipments, Tracking, Fleet', 'Lacak resi dengan riwayat perjalanan', 'Status pengiriman dan armada kendaraan', 'Grafik SVG tanpa library, menu geser di HP'], 'v1.0.0', null, 'free-logistics-dashboard/free-logistics-dashboard-v1.0.0.zip', 'Terbit'),
('kosan-rental-property-dashboard', 'Kosan Rental Property Dashboard', 'Dashboard kos dan kontrakan: pemasukan sewa, unit terisi, data penyewa, dan tagihan bulanan.', 'Dashboard untuk pemilik atau pengelola kos dan kontrakan. Overview berisi pemasukan sewa, jumlah unit terisi, dan tunggakan, halaman Units dengan filter properti dan status, direktori penyewa dengan masa kontrak, serta tagihan sewa bulanan dengan status lunas dan terlambat.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-property-dashboard/card.webp', array['/templates/free-property-dashboard/desktop-1.webp', '/templates/free-property-dashboard/desktop-2.webp', '/templates/free-property-dashboard/desktop-3.webp', '/templates/free-property-dashboard/desktop-4.webp'], array['/templates/free-property-dashboard/mobile-1.webp'], array['4 halaman: Overview, Units, Tenants, Payments', 'Tagihan sewa bulanan dengan status', 'Filter per properti dan status unit', 'Export CSV, menu geser di HP'], 'v1.0.0', null, 'free-property-dashboard/free-property-dashboard-v1.0.0.zip', 'Terbit'),
('saji-restaurant-dashboard', 'Saji Restaurant Dashboard', 'Dashboard restoran: penjualan, pesanan dine-in/takeaway/delivery, tampilan dapur, dan menu.', 'Dashboard operasional restoran. Overview berisi penjualan per jam dan denah meja, halaman Orders dengan tab dine-in, takeaway, dan delivery, layar dapur model kanban (Baru, Dimasak, Siap), serta daftar menu dengan tombol tersedia atau habis.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-restaurant-dashboard/card.webp', array['/templates/free-restaurant-dashboard/desktop-1.webp', '/templates/free-restaurant-dashboard/desktop-2.webp', '/templates/free-restaurant-dashboard/desktop-3.webp', '/templates/free-restaurant-dashboard/desktop-4.webp'], array['/templates/free-restaurant-dashboard/mobile-1.webp'], array['4 halaman: Overview, Orders, Kitchen, Menu', 'Layar dapur model kanban', 'Tab pesanan dine-in, takeaway, delivery', 'Tombol menu tersedia / habis, menu geser di HP'], 'v1.0.0', null, 'free-restaurant-dashboard/free-restaurant-dashboard-v1.0.0.zip', 'Terbit')
on conflict (slug) do update set
  title = excluded.title,
  summary = excluded.summary,
  description = excluded.description,
  category = excluded.category,
  tech_stack = excluded.tech_stack,
  price = 0,
  demo_url = null,
  thumbnail_url = excluded.thumbnail_url,
  screenshots = excluded.screenshots,
  mobile_screenshots = excluded.mobile_screenshots,
  features = excluded.features,
  status = 'Terbit';
-- storage_file_path sengaja tidak ditimpa supaya file zip yang sudah di-upload dari admin tetap terpakai.
